/*
 * The Japanese and Chinese faces' slices: several hundred @font-face rules
 * (about 70 KB gzipped), kept out of the stylesheet that holds up the first
 * paint. Each page's entry imports this module, which attaches them once the
 * page is running; a stylesheet added from a script never blocks rendering.
 * Until it arrives the front page's own Japanese and Chinese are already set
 * from its cut in fonts.css, and anything else waits in a system face
 * (font-display: swap). Generated by scripts/fonts.mjs.
 */
import href from "./styles/fonts-cjk.css?url";

if (!document.querySelector("link[data-fonts-cjk]")) {
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = href;
  link.dataset.fontsCjk = "";
  document.head.append(link);
}
